// Stable paths generated by CurveMole's existing screenshot workflow.
// Branch and paths can be changed here without touching the page layout.
const screenshotSource = {
  base: 'https://raw.githubusercontent.com/SebRoLENS/curvemole/main/docs/screenshots/',
  files: {fit:'dark-mode-fit.png',overlay:'multi-spectrum-overlay.png',waterfall:'waterfall-view.png'},
  refreshMs: 5 * 60 * 1000
};
let screenshotRequest = 0;
function setScreenshot(img, key) {
  if (!screenshotSource.files[key]) return;
  const changed = img.dataset.screenshot !== key;
  img.dataset.screenshot = key;
  // A bundled fallback ensures a complete page offline or if GitHub is unavailable.
  if (changed) img.src = 'assets/' + key + '.png';
  const request = String(++screenshotRequest);
  img.dataset.request = request;
  const latest = new Image();
  latest.onload = () => {
    if (img.dataset.request === request && img.dataset.screenshot === key) {
      img.src = latest.src;
      img.dataset.source = 'github';
    }
  };
  latest.onerror = () => {}; // Keep the last successful image; never show a broken screenshot.
  latest.src = screenshotSource.base + screenshotSource.files[key] + '?v=' + Math.floor(Date.now()/screenshotSource.refreshMs);
}
function refreshScreenshots() {
  if (!document.hidden) document.querySelectorAll('[data-screenshot]').forEach(img => setScreenshot(img,img.dataset.screenshot));
}
refreshScreenshots();
setInterval(refreshScreenshots, screenshotSource.refreshMs);
document.addEventListener('visibilitychange',refreshScreenshots);
